// Get input data with error handling
const inputData = $input.all();

// Check if inputData exists and has items
if (!inputData || inputData.length === 0) {
  throw new Error("No input data received");
}

// Extract function arguments from the correct path based on your data structure
const functionArgs = inputData[0]?.json?.toolCalls?.[0]?.function?.arguments || 
                    inputData[0]?.toolCalls?.[0]?.function?.arguments ||
                    inputData[0]?.function?.arguments ||
                    inputData[0]?.json || 
                    inputData[0];

const name = functionArgs?.name;
const phone = functionArgs?.Phone || functionArgs?.phone; // Handle both cases
const dob = functionArgs?.dob || functionArgs?.DOB || functionArgs?.dateOfBirth; // Handle variations
const date = functionArgs?.date || functionArgs?.appointmentDate; // Handle variations

console.log("Raw functionArgs:", JSON.stringify(functionArgs, null, 2));
console.log("Name:", JSON.stringify(name));
console.log("Phone:", JSON.stringify(phone));
console.log("DOB:", JSON.stringify(dob));
console.log("Date:", JSON.stringify(date));
console.log("Name truthy check:", !!name, "length:", name?.length);
console.log("Phone truthy check:", !!phone, "length:", phone?.length);
console.log("Date truthy check:", !!date, "length:", date?.length);

// More robust validation - check for empty strings and whitespace
const isValidField = (field) => field && typeof field === 'string' && field.trim().length > 0;

const missingFields = [];
if (!isValidField($input.first().json.body.message.toolCalls[0].function.arguments.name)) missingFields.push("name");
if (!isValidField($input.first().json.body.message.toolCalls[0].function.arguments.Phone)) missingFields.push("phone number");
if (!isValidField($input.first().json.body.message.toolCalls[0].function.arguments.dob)) missingFields.push("appointment dob");
// Only check for DOB if it's actually required for your use case
// if (!isValidField(dob)) missingFields.push("date of birth");

if (missingFields.length > 0) {
  throw new Error(`Missing required details: ${missingFields.join(", ")}. Please provide all required information.`);
}

// Return the processed data
return inputData;
